#include <iostream>
#include <algorithm>
using namespace std;

long long total_moves = 0;

int countDigits(long long num) {
    int count = 0;
    while (num != 0) {
        num /= 10;
        count++;
    }
    return count;
}

long long getThreshold(long long num) {
    int digits = countDigits(num);
    long long base = 0, factor = 1;
    for (int i = 0; i < digits; i++) {
        base += factor;
        factor *= 10;
    }
    if (base <= num) return base;
    return (base - 1) / 10;
}

long long recursiveSolve(long long n) {
    if (n <= 6) return n;
    if (n <= 11) return 13 - n;
    long long base_num = getThreshold(n);
    long long boundary = base_num * 10 + 1;
    if (n % base_num == 0) {
        long long quotient = n / base_num;
        if (n <= boundary / 2 + base_num) return countDigits(base_num) * quotient;
        else {
            long long diff = recursiveSolve(boundary - n);
            return countDigits(boundary) + diff;
        }
    } else {
        long long lower_bound = (n / base_num) * base_num;
        long long upper_bound = (n / base_num + 1) * base_num;
        long long res = recursiveSolve(lower_bound) + recursiveSolve(n - lower_bound);
        if (n > boundary / 2) {
            res = min(recursiveSolve(lower_bound) + recursiveSolve(n - lower_bound),
                      countDigits(boundary) + recursiveSolve(boundary - n));
        }
        return res;
    }
}

int main() {
    long long n;
    cin >> n;
    cout << recursiveSolve(n) << endl;
    return 0;
}
